Generate a standalone C reproducer that triggers this vulnerability:

File: bfd/coff-rs6000.c
Line: 4175
Function: xcoff_generate_rtinit
Bug type: integer-overflow
CWE: CWE-190
Explanation: data_buffer_size is computed as 0x40 + initsz + finisz (with initsz/finisz derived from 1 + strlen). If initsz or finisz are very large, the addition can overflow bfd_size_type, causing bfd_zmalloc to allocate a too-small buffer. Subsequent memcpy calls write initsz/finisz bytes at offsets 0x40 and 0x40+initsz (lines 4185 and 4194), leading to heap buffer overflow.

Source context:
```c
     4135:   filehdr.f_opthdr = 0;
     4136:   filehdr.f_flags = 0;
     4137: 
     4138:   /* section header */
     4139:   memset (scnhdr_ext, 0, SCNHSZ);
     4140:   memset (&scnhdr, 0, sizeof (struct internal_scnhdr));
     4141:   memcpy (scnhdr.s_name, data_name, strlen (data_name));
     4142:   scnhdr.s_paddr = 0;
     4143:   scnhdr.s_vaddr = 0;
     4144:   scnhdr.s_size = 0;    /* set below */
     4145:   scnhdr.s_scnptr = FILHSZ + SCNHSZ;
     4146:   scnhdr.s_relptr = 0;  /* set below */
     4147:   scnhdr.s_lnnoptr = 0;
     4148:   scnhdr.s_nreloc = 0;  /* either 1 or 2 */
     4149:   scnhdr.s_nlnno = 0;
     4150:   scnhdr.s_flags = STYP_DATA;
     4151: 
     4152:   /* .data
     4153:      0x0000	      0x00000000 : rtl
     4154:      0x0004	      0x00000010 : offset to init, or 0
     4155:      0x0008	      0x00000028 : offset to fini, or 0
     4156:      0x000C	      0x0000000C : size of descriptor
     4157:      0x0010	      0x00000000 : init, needs a reloc
     4158:      0x0014	      0x00000040 : offset to init name
     4159:      0x0018	      0x00000000 : flags, padded to a word
     4160:      0x001C	      0x00000000 : empty init
     4161:      0x0020	      0x00000000 :
     4162:      0x0024	      0x00000000 :
     4163:      0x0028	      0x00000000 : fini, needs a reloc
     4164:      0x002C	      0x00000??? : offset to fini name
     4165:      0x0030	      0x00000000 : flags, padded to a word
     4166:      0x0034	      0x00000000 : empty fini
     4167:      0x0038	      0x00000000 :
     4168:      0x003C	      0x00000000 :
     4169:      0x0040	      init name
     4170:      0x0040 + initsz  fini name */
     4171: 
     4172:   data_buffer_size = 0x0040 + initsz + finisz;
     4173:   data_buffer_size = (data_buffer_size + 7) &~ (bfd_size_type) 7;
     4174:   data_buffer = NULL;
>>>  4175:   data_buffer = (bfd_byte *) bfd_zmalloc (data_buffer_size);
     4176:   if (data_buffer == NULL)
     4177:     return false;
     4178: 
     4179:   if (initsz)
     4180:     {
     4181:       val = 0x10;
     4182:       bfd_h_put_32 (abfd, val, &data_buffer[0x04]);
     4183:       val = 0x40;
     4184:       bfd_h_put_32 (abfd, val, &data_buffer[0x14]);
     4185:       memcpy (&data_buffer[val], init, initsz);
     4186:     }
     4187: 
     4188:   if (finisz)
     4189:     {
     4190:       val = 0x28;
     4191:       bfd_h_put_32 (abfd, val, &data_buffer[0x08]);
     4192:       val = 0x40 + initsz;
     4193:       bfd_h_put_32 (abfd, val, &data_buffer[0x2C]);
     4194:       memcpy (&data_buffer[val], fini, finisz);
     4195:     }
     4196: 
     4197:   val = 0x0C;
     4198:   bfd_h_put_32 (abfd, val, &data_buffer[0x0C]);
     4199: 
     4200:   scnhdr.s_size = data_buffer_size;
     4201: 
     4202:   /* string table */
     4203:   string_table_size = 0;
     4204:   if (initsz > 9)
     4205:     string_table_size += initsz;
     4206:   if (finisz > 9)
     4207:     string_table_size += finisz;
     4208:   if (string_table_size)
     4209:     {
     4210:       string_table_size += 4;
     4211:       string_table = (bfd_byte *) bfd_zmalloc (string_table_size);
     4212:       if (string_table == NULL)
     4213: 	{
